/* V7.5 playable adaptation. Chinese production text; English working translation.
 * The original manuscript remains in story/v7.5/source.md. No scoring of moral positions.
 * Missing language fields deliberately fall back to English; never label them translations.
 */
(function (root) {
  'use strict';
  const L = (zh, en) => ({ 'zh-Hans': zh, en });
  const N = (id, actor, label, text, requires = [], interaction) => ({ id, actor: actor === 'either' ? 'both' : actor, label, text, requires, ...(interaction ? { interaction } : {}) });
  const C = (id, label, feedback, correct = true) => ({ id, label, feedback, correct });
  const Q = (prompt, choices) => ({ type: 'choice', prompt, choices });
  const chapters = [
    {
      id: 'london', number: 4, title: L('那句还没印出来的话', 'The Sentence Not Yet Printed'), bg: 'assets/london.webp',
      opening: L('伦敦的雨很细，屋檐接不住。维卡接到清理一张危险联络网的任务；诺伊却先去扶住了印刷铺摇晃的后门。', 'London rain slips past the eaves and down every collar. Vika has orders to dismantle a dangerous network. Noyi begins by holding open a printer’s crooked back door.'),
      nodes: [
        N('ld_press', 'vika', L('让印刷机通过后门', 'Get the press through the door'), L('机器的一角卡住了。前面的瘦老人骂道：“从前没人敢这样修门。”艾达用肩膀抵着门框：“那就请您从前的臣民过来帮忙。”\n诺伊笑着让维卡先卸下活动把手。他们转过机器，终于挤进屋。老人曾是秦朝的皇帝，临终前被时序局接走治病，如今在伦敦付房租，也赔过玻璃。\n“你们又来替别人做决定了？”他问。\n“我来查一份名册。”\n“那你来晚了。名册有好几种。”', 'A corner of the press catches. “Nobody used to dare build doors like this,” the thin old man snaps. Ada braces the frame with her shoulder. “Then summon your former subjects to help.”\nNoyi points to the detachable handle. They remove it, turn the press, and squeeze through. The old man was once emperor of Qin. The Bureau brought him out of his final illness; in London he has learned to pay rent and replace broken windows.\n“Here to make other people’s decisions again?” he asks.\n“I’m here for a register.”\n“You’re late. There’s more than one.”')),
        N('ld_registers', 'noyi', L('辨认两种地址', 'Separate the two kinds of address'), L('灯下的两册名录有许多相同姓名。一册记着军火的收货日期，另一册记着逃难家庭的临时住处。诺伊认出一处地址：昨晚她在那里替孩子烘过袜子。\n艾达将纸压住：“别把这页拿去当证据公开。明天他们还得睡在那里。”\n维卡的任务要求切断整张网。可同一个搬运工，会替商人运枪，也会把床让给别人。姓名相同，不等于事情相同。', 'The two registers share many names. One gives weapons delivery dates; the other lists temporary homes for fleeing families. Noyi recognizes an address where she dried a child’s socks last night.\nAda holds that page down. “Don’t publish this as evidence. They have to sleep there tomorrow.”\nVika’s orders cover the whole network. Yet the same porter may carry weapons for a merchant and lend his own bed to a stranger. Matching names do not make matching actions.'), ['ld_press'], Q(L('哪一种整理方式保留了可以核实的区别？', 'Which arrangement preserves the distinctions you can verify?'), [
          C('separate', L('确证军火单独归档；住址交艾达保管；未核实项留下标记', 'File verified arms deals separately; leave addresses with Ada; mark unknown links'), L('三叠纸没有变成一个简单答案。未核实的联系仍然存在。', 'Three piles of paper do not make one simple answer. The unverified links remain.')),
          C('all', L('姓名重复就把两册合成同一份罪证', 'Treat matching names as one incriminating list'), L('诺伊指着一个孩子的寄住地址：“这一行证明有人借出了床，不能证明他买过枪。”', 'Noyi points at a child’s lodging. “This line establishes a borrowed bed, not a purchase of guns.”'), false)
        ])),
        N('ld_warning', 'either', L('听完尚未排版的争吵', 'Hear the argument before typesetting'), L('老人要把港口警报扣住一天，以换谈判时间。艾达要立刻印出来。\n“港口的人知道有人替他们押上这一天吗？”维卡问。\n“知道了他们就会乱。你没见过谈判快成了又崩掉，会死多少人。”\n艾达举起校样：“第一页你让印，第二页我写你，你就不让？”\n“第二页写错了。”\n“你付的是搬机器的钱，不是买我的编辑权。”\n老人说她在从前早就——说到一半停住了。门外送铅字的少年抖着手，等他们让出一块避雨的地方。', 'The old man wants to hold the harbour warning for one day to keep negotiations alive. Ada wants it printed now.\n“Do the people at the harbour know you’ve wagered their day?” Vika asks.\n“They’d panic. You haven’t seen how many die when a negotiation almost succeeds and then falls apart.”\nAda raises her proof. “You approve page one. But page two criticizes you, so that one can’t run?”\n“Page two is wrong.”\n“You paid to move a press. You didn’t buy my editorial decisions.”\nThe old man begins explaining what would once have happened to her, then stops. Outside, a boy carrying type waits for a dry place to stand.'), ['ld_registers']),
        N('ld_report', 'vika', L('看维卡交出报告', 'Watch Vika submit his report'), L('应当写下的是“清理未完成”。维卡知道。还有几条联系尚无法核实，警报公开后会发生什么，也没有人能够替所有家庭承担。\n他却在状态栏填了“风险网络已解除”。笔尖在最后一个字母下留下墨点。\n这是维卡自己的决定。纸上的谎话没有因为他想保护救济网就变成事实。诺伊看到了那个墨点，问他要不要重写。他把纸折了起来。\n楼下传来艾达催纸的声音。他们谁也没再提报告。', 'The honest status would be “Clearance incomplete.” Vika knows it. Several links remain unverified, and no one can bear the consequences of publication on behalf of every family.\nHe writes “Risk network dismantled.” Ink pools under the final letter.\nThis is Vika’s own decision. His wish to protect the relief network does not turn the report into a fact. Noyi notices the blot and asks whether he wants to rewrite it. He folds the paper.\nBelow them, Ada calls for more stock. Neither mentions the report again.'), ['ld_warning']),
        N('ld_letters', 'noyi', L('把两种来信放在同一桌上', 'Put both kinds of letter on the table'), L('警报登在第三版。有人赶在封港前离开，也有两户人家因谈判破裂失去了收入。桌上有感谢信，还有威胁烧掉印刷机的信。\n老人把一封信塞给维卡，又将另外两封压在上面。\n“谁都能从里面挑到证明自己正确的一页。”\n诺伊把所有信按日期排好，没有替任何一种信加上更醒目的封套。艾达还欠着纸钱，老人已经过去替她讨价还价。他反对她印警报，也不打算让供货商借机欺负她。', 'The warning runs on page three. Some families escape before the harbour closes; two lose their income when the talks collapse. The table holds thanks and threats to burn the press.\nThe old man pushes one letter at Vika, then lays two more over it.\n“Anyone can pick a page that proves them right.”\nNoyi files every letter by date. Neither kind receives a brighter cover. Ada still owes money for paper. The old man goes to bargain with her supplier. He opposed the warning; that does not mean he will let the supplier exploit her.'), ['ld_report']),
        N('ld_ink', 'either', L('在后门洗去手上的墨', 'Wash the ink off at the back door'), L('第三盆水仍是灰的。维卡问诺伊怎么认识那位老人。\n“他替我借过一张通行证。”\n“借？”\n“至今没还。”\n维卡抬起手：“你早知道我是谁。”\n“嗯。我在旧任务档案里读到过你的名字。你有时会把本来该删掉的东西留下。”\n“所以你找我。”\n“不是因为你比别人善良。我没有别的理由。”\n雨滴落进他们之间的盆里。维卡还没回答，艾达便从窗口叫他们搬纸。他慢了半步，最重的箱子留给了他。诺伊没有替他接过去。', 'The third basin is still grey. Vika asks how Noyi knows the old man.\n“He borrowed a travel pass for me.”\n“Borrowed?”\n“I haven’t returned it.”\nVika lifts his hands from the water. “You knew who I was.”\n“Yes. Your name was in an old assignment file. Sometimes you keep things you’re supposed to discard.”\n“So you sought me out.”\n“Not because you’re kinder than everyone else. I had no other reason.”\nRain falls into the basin between them. Before Vika can answer, Ada calls for help. His hesitation earns him the heaviest box. Noyi does not take it from him.'), ['ld_letters'])
      ]
    },
    {
      id: 'classroom', number: 5, title: L('第三根管子', 'The Third Pipe'), bg: 'assets/classroom.webp',
      opening: L('伦敦的补充记录送到了冯岑桌上。站区里一间退役实验室也重新开门了。墙上十年前的课表写着“自主实验”，下面贴满改期通知。', 'The supplementary London records reach Feng Cen. An old laboratory reopens elsewhere in the station. Beneath “Independent experiment” on its ten-year-old timetable is a row of postponement notices.'),
      nodes: [
        N('cl_permission', 'vika', L('面对对不上的两份记录', 'Face the mismatched records'), L('“伦敦报告和现场记录对不上。”冯岑没有提高声音。\n维卡试图解释救济网。他听完，只说：“别为了证明自己替别人说话，再替自己发明一个理由。”\n诺伊把借来的证件、旧线路和未来资料交给调查员。主管给她临时身份，由维卡陪同核验；不是因为他相信她，而是资料可以检查。\n米拉发来实验室的有条件许可：启动前必须由当班人员核实隔离。\n“红胶带那边归运行部。”她说，“能进教室，不等于能动设备。”', '“Your London report disagrees with the field record.” Feng Cen does not raise his voice.\nVika starts explaining the relief network. Feng lets him finish. “Don’t invent another excuse for yourself to prove you speak for other people.”\nNoyi surrenders the borrowed credentials, old routes, and future records. She receives temporary status for supervised verification, not an endorsement of her claims.\nMira’s laboratory permit is conditional: the duty team must verify isolation before startup.\n“Beyond the red tape is Operations,” she says. “Permission to enter a classroom is not permission to operate its equipment.”')),
        N('cl_paperplane', 'noyi', L('给纸飞机找一张实验台', 'Find the paper plane its own bench'), L('一个女孩要把纸飞机放进恒温箱，说这是研究风力。\n“为什么不能试？”\n“里面有别人明天要用的培养样品。你的飞机有自己的实验台。”\n系统把压力差讲得很清楚。一个少年还是想自己讲，讲到一半，发现整班正跟着他走向错误答案。\n“怎么办？”\n“从这里重来。也可以看系统的。”诺伊说。\n他咬着粉笔想了一会儿，擦掉了前两行。没有掌声，后排有人催他快点。', 'A girl wants to put her paper plane inside the incubator. She calls it wind research.\n“Why can’t I try?”\n“Those cultures belong to someone who needs them tomorrow. Your plane has its own bench.”\nThe system explains pressure differences clearly. A boy still wants to explain them himself. Halfway through, he realizes the class is following him towards the wrong answer.\n“What now?”\n“Start again here. Or use the system’s explanation,” Noyi says.\nHe bites the chalk, thinks, and erases his first two lines. Nobody applauds. Someone at the back tells him to hurry.'), ['cl_permission']),
        N('cl_watch', 'vika', L('把表盒交给萨米', 'Give Sami the watch box'), L('萨米终于来取杏的礼物。看见封口没拆，他竟有点不好意思。\n“我还以为你拆了。”\n“怕你女儿长大后告我。”\n萨米戴上表，答应先试走两天。盒里还剩备用表带，维卡随手收进抽屉，说下次带给他。\n“她总问几点回来。”萨米看着指针，“这至少不会临时发一条建议延迟。”\n他又从口袋摸出酸糖。第一颗把他酸得皱眉，下一颗仍照样拆开。', 'Sami finally collects Xing’s birthday present. The untouched seal makes him look faintly embarrassed.\n“I thought you’d taken it apart.”\n“I was afraid your daughter would sue me when she grew up.”\nHe puts the watch on to test it for a couple of days. Vika puts the spare strap in a drawer and promises to bring it next time.\n“She keeps asking when I’ll be home.” Sami studies the hands. “At least this won’t send her a recommendation to postpone.”\nHe unwraps a sour sweet. The first makes him grimace. He unwraps another anyway.'), ['cl_permission']),
        N('cl_gravity', 'either', L('试摆不用热源的水路', 'Arrange the water circuit without heat'), L('萨米画了两套替代装置。一套只用杯子，另一套用液位差。维卡把盛水的杯子抬高，细管里便有水流下来。\n“这条路你看得见。”萨米说，“哪儿漏，也容易查。”\n他们准备加热试验已经五周。一个孩子画的曲线贴满整面墙。维卡仍想亲眼看看它会怎样，把那份好奇心写成了“教学目标”。\n诺伊喜欢杯子装置，也喜欢墙上的曲线。她没有把后者收下来。', 'Sami sketches two alternatives: cups, and a circuit driven by water level. Vika lifts the upper cup. Water runs down the narrow tube.\n“You can see this whole route,” Sami says. “And trace a leak.”\nThey have prepared the heated trial for five weeks. One child’s predictions cover a wall. Vika still wants to know what the curve will do; on the application he calls that wish a “teaching objective.”\nNoyi likes the cups. She likes the curves too. She does not take them down.'), ['cl_paperplane', 'cl_watch'], Q(L('不用接入站区热源，怎样让透明管中有流动？', 'How can you create flow without connecting to the station’s heat supply?'), [
          C('height', L('让上杯高于下杯，在下方放接水盆', 'Raise the upper cup and place a catch basin below'), L('水依靠重力流动。这个小实验可以随时停下，全部连接都在眼前。', 'Gravity drives the water. Every connection is visible, and the small experiment can be stopped at once.')),
          C('label', L('沿用旧标签，把看不见的管口接上', 'Connect the hidden pipe using its old label'), L('萨米把接头推回来：“标签说的是过去。先用你能一眼看全的这几只杯子。”', 'Sami pushes the connector back. “A label describes the past. Start with the cups you can see.”'), false)
        ])),
        N('cl_bypass', 'noyi', L('沿红胶带看到后墙', 'Follow the red tape to the back wall'), L('旧台架的主泵停了，教学端也限了功率，但换热腔可能仍通过检修旁路连着高温主循环。大修占着当班人员，现场核验要等十六天。那以后，教室将让给康复中心。\n萨米摸到一张旧标签。\n“这条旁路停用多久？”\n“图纸写停用。”维卡说。\n“我会读图纸。我问的是现场。”\n他要去修后区主泵，不能同时核验这里。临走前他说：“先做不接热源的。觉得有意思可以，连接还得一根根查。”', 'The old rig’s pump is stopped and its teaching heater has a power limit. Its heat exchanger may still connect to the station’s hot main loop through a maintenance bypass. The duty team cannot trace it for sixteen days. By then, rehabilitation patients will need the room.\nSami touches an old label.\n“How long has this bypass been out of service?”\n“The drawing says it is,” Vika replies.\n“I can read drawings. I’m asking about the pipe.”\nHe must repair the rear main pump and cannot verify both places. As he leaves he says, “Start without heat. Being interested is fine. Connections still need checking one by one.”'), ['cl_gravity'])
      ]
    },
    {
      id: 'accident', number: 6, title: L('你签过字', 'You Signed'), bg: 'assets/classroom.webp',
      opening: L('米拉没有来。电子许可上亮着黄色警告：“现场隔离状态未核实，建议推迟试验。”这章的事故源于角色作出的决定；玩家负责查看、记录与救援。', 'Mira cannot come. The permit shows an amber warning: “Physical isolation unverified. Postponement recommended.” The accident in this chapter follows the characters’ decisions. Your actions concern observation, recording, and rescue.'),
      nodes: [
        N('ac_assumption', 'vika', L('打开安全计算的前提', 'Open the safety calculation’s assumptions'), L('两只阀门关闭，压力表归零。系统算出：在提交的连接假设成立时，低功率试验风险低于阈值。\n假设写得清楚：旧换热腔与主循环已经物理断开。可后墙最后一段管线，他们进不去，当班人员也来不了。\n维卡把那行字放大。计算没有证明现场隔离，它只证明了一张特定连接图上的结果。两者只差几个字，差的却是一段真实的管子。', 'Two valves are closed. The gauge reads zero. The system finds the low-power trial below the risk threshold—provided the submitted connection assumptions are true.\nOne assumption is explicit: the old exchanger has been physically disconnected from the main loop. They cannot enter the last section behind the wall, and the duty team is unavailable.\nVika enlarges the line. The calculation establishes the result for a particular circuit diagram. It does not establish which circuit actually exists.'), [], Q(L('把哪一句写进观察记录，才没有超出证据？', 'Which observation stays within the evidence?'), [
          C('conditional', L('计算是有条件的；后区实际连接仍未核实', 'The calculation is conditional; the rear connection remains unverified'), L('这条观察保存在日志里。记录正确并不意味着有权解除隔离要求。', 'The observation is saved. Recording it correctly does not authorize anyone to waive physical verification.')),
          C('guarantee', L('系统已经保证现场安全', 'The system has guaranteed the actual site is safe'), L('黄色警告仍在。系统从未保证那个未经查看的连接。', 'The amber warning remains. The system has never vouched for the unseen connection.'), false)
        ])),
        N('ac_signature', 'either', L('见证他们没有停下的片刻', 'Witness the moment they do not stop'), L('“就别做了。”诺伊说。\n“场地明天交还。”\n“所以更应该停。”\n维卡将热量降到四分之一。他同意了一个更小的试验，却把“更小”当作“已经隔离”，在确认栏签下名字。旧流程只检查签名完整，没有核对他是否是当班核验员。\n诺伊在记录本上圈住警告，没有代签，也没有去运行部取消许可。两人都希望另一个人把事情停下。\n维卡知道理由很差。他仍没有撤回。', '“Then we don’t do it,” Noyi says.\n“The room goes back tomorrow.”\n“All the more reason to stop.”\nVika reduces the heat to a quarter. He agrees to a smaller trial, then treats “smaller” as “isolated” and signs the confirmation. The legacy workflow checks that signatures are present, not whether the signer belongs to the duty verification team.\nNoyi circles the warning in her notebook. She does not countersign; she also does not go to Operations to cancel the permit. Each hopes the other will stop it.\nVika knows his reason is poor. He does not withdraw.'), ['ac_assumption']),
        N('ac_locker', 'noyi', L('看着萨米收好手表', 'Watch Sami put away the watch'), L('萨米来拿手套，随后要和安德烈检修后区泵轴。\n“后区那段也走过了？”他问。\n维卡说：“核验表已经签了。”\n萨米看了一眼签名。他摘下杏的表，锁进自己的柜子。最小的孩子贴着透明罩，他让孩子别把鼻子伸进去。\n“我又不是鱼。”\n“鱼至少知道水在哪里。”\n门关上。前五分钟，曲线很好看。一个孩子叫出声，说自己的预测对了一半。', 'Sami comes for his gloves before inspecting the rear pump bearing with Andrei.\n“Did you trace the rear section too?” he asks.\n“The verification form is signed,” Vika says.\nSami glances at it, removes Xing’s watch, and locks it in his cabinet. He tells the smallest child not to press a nose against the shield.\n“I’m not a fish.”\n“A fish at least knows where the water is.”\nThe door closes. For five minutes the curve is beautiful. A child shouts that half of his prediction was right.'), ['ac_signature']),
        N('ac_stop', 'noyi', L('发现回落异常，帮助撤离', 'Notice the slow decay and help evacuate'), L('一个测点回落得太慢。系统建议停止，诺伊按下按钮。教学热源停了。十多秒以后，后墙响了一声闷响。\n维卡冲向门，热气从门缝喷出来。诺伊抓住他的领子，把他拉回警戒线。米拉正在远端切断主泵。\n走廊里的孩子需要一条畅通的出口。诺伊把最小的交给老师，逐个对照名单。她的手背已经烫起水泡。没有人因为按下停机按钮就能收回最初那股热流。', 'One reading falls too slowly. The system recommends stopping. Noyi presses the button. The teaching heater stops. More than ten seconds later, a dull blow sounds behind the wall.\nVika runs to the door. Heat jets through its seam. Noyi drags him back by the collar while Mira shuts the main pump from the control room.\nThe children need a clear exit. Noyi passes the youngest to another teacher and checks every name. Blisters rise on the back of her hand. Stopping the heater cannot recall the first surge.'), ['ac_locker'], Q(L('警戒门后仍有余压。现在怎样帮助救援？', 'Residual pressure remains beyond the barrier. How can you help?'), [
          C('clear', L('保持门口畅通，把人员名单交给运行部', 'Keep access clear and hand the roster to Operations'), L('老师带走孩子，救援人员拿到完整名单。维卡留在警戒线外。', 'The teacher takes the children out. Responders receive the complete roster. Vika stays outside the barrier.')),
          C('open', L('自己打开高温区的门', 'Open the hot-zone door yourself'), L('诺伊拦住门柄：“不是多进去一个人，里面的人就能出来。”救援员需要先确认压力。', 'Noyi blocks the handle. “Adding another person inside won’t bring them out.” Responders must first confirm the pressure.'), false)
        ])),
        N('ac_path', 'vika', L('追出未在图上的热流', 'Trace the heat missing from the diagram'), L('第三条检修旁路仍连接高温主循环。试验脉冲触发了旧联锁的压力补偿，高压热流从另一侧进入维修支路，冲开正在拆检的接头。教学端很小的功率，没有限制另一侧的能量。\n标签没更新，交接没签完，维卡又把未检查写成已确认。三件事没有互相抵消。\n主泵终于停了，余压仍须缓慢释放。安德烈的通讯里只有喘气和金属摩擦。维卡反复看那段路径，像多看一遍就能让它短一点。', 'A third maintenance bypass still joins the hot main loop. The test pulse triggers an old pressure-compensation interlock. Hot pressurized fluid enters the maintenance branch from the other side and ruptures a joint being dismantled. Low teaching power never limited the energy on that other side.\nThe label was outdated; handover was unfinished; Vika declared an unchecked condition verified. None cancels the others.\nThe main pump is stopped, but pressure must bleed away. Andrei’s radio carries breathing and scraping metal. Vika traces the route again, as if another reading could make it shorter.'), ['ac_stop']),
        N('ac_stretchers', 'either', L('为担架让出走廊', 'Make room for the stretchers'), L('医生抬出两副担架。安德烈呻吟着，防护服黏在手臂上。萨米的担架盖着白色应急毯。\n维卡走上去，张开口，什么声音也没有。诺伊站着不动，直到医生让她让路。\n当夜，调查组封存了原始警告和签名。工人从柜子里取出那只仍在走的表，放进写着萨米工号的证物袋。\n维卡想起抽屉里的备用表带。他曾经觉得，把东西交出去是一件随时都来得及做的事。', 'Two stretchers emerge. Andrei is moaning, protective clothing stuck to his arm. Sami’s is covered by a white emergency blanket.\nVika steps forward, opens his mouth, and makes no sound. Noyi stands motionless until a doctor asks her to move.\nThat night the investigators seal the original warning and signatures. A worker takes the still-running watch from the locker and bags it under Sami’s employee number.\nVika remembers the spare strap in his drawer. Handing over an object had once seemed like something there would always be time to do.'), ['ac_path'])
      ]
    }
  ];
  chapters.push(
    {
      id: 'aftermath', number: 7, title: L('九点十七分', 'Nine Seventeen'), bg: 'assets/aftermath-matched.webp',
      opening: L('家属到来以前，谁也不能拆开证物袋。遗物室门外，维卡与诺伊之间隔着一个空座。走廊的钟从九点十六跳到了十七。', 'Nobody may open the belongings bags before the family arrives. Outside the property room, an empty chair separates Vika and Noyi. The corridor clock changes from 9:16 to 9:17.'),
      nodes: [
        N('af_yesterday', 'vika', L('问那个已经知道答案的问题', 'Ask the question whose answer he knows'), L('“能回前一天吗？”维卡问。\n冯岑停住：“你要回哪一个前一天？”\n“他进去以前。”\n“萨米在站区生活了十一年。”\n年代通道能去外部历史，站区却没有通往自己昨天的门。改掉萨米出生时的一件事，也不会让已离开原年代的他重新活一次。\n“你以前说这规则公平。”\n“我只想过它替别人保住什么。”\n冯岑没有继续问。主泵停了，孩子们今晚没有热水。他让维卡去送毯子。', '“Can we go back one day?” Vika asks.\nFeng stops. “Which yesterday?”\n“Before he went inside.”\n“Sami lived in this station for eleven years.”\nThe gates reach external history, never the station’s own yesterday. Changing something at Sami’s birth would not replay the life of a man who had already left that era.\n“You used to call this rule fair.”\n“I only thought about what it preserved.”\nFeng does not press him. The main pump is off; the children have no hot water tonight. He asks Vika to bring blankets.')),
        N('af_property', 'noyi', L('把通向遗物室的路让给家属', 'Leave the way to the property room clear'), L('莱拉牵着杏来，孩子的袖口卷了两圈。表、手套、钥匙、酸糖，一样一样放进盒子。货车在外面倒车，杏忽然回头，像有人叫了她。\n“签字的是谁？”莱拉问。\n维卡站起来。\n“他出门前问过你吗？”\n“问过。我说已经确认隔离。”\n“明白了。以后请别再用那句话向我解释。”\n诺伊没有递上自己准备的说明。那条走廊不是她要求理解的地方。', 'Laila arrives holding Xing’s hand. The child’s sleeves are folded twice. Watch, gloves, keys, sour sweets: each goes into the box. A truck reverses outside. Xing turns as though someone has called her.\n“Who signed?” Laila asks.\nVika stands.\n“Did he ask you before he went in?”\n“Yes. I said isolation was confirmed.”\n“I understand. Please don’t use that sentence to explain it to me again.”\nNoyi does not offer her prepared account. This corridor is not where she can demand understanding.'), ['af_yesterday']),
        N('af_record', 'vika', L('交出原始记录', 'Submit the original records'), L('独立安全调查与司法监察调走原始数据。维护标签、部门交接、越权签字各有责任；维卡和诺伊失去操作许可，承担直接责任。\n系统的黄色警告仍完整存在。安德烈的治疗、劳动能力评估、赔偿，一项项进入长期文件。\n维卡给莱拉写到第三封信，律师寄回一张纸：赔偿转入约定账户，不要再附信。\n他把已写好的信放到一旁。这次表格没有替他说一句漂亮话。', 'Independent safety investigators and judicial oversight take the original data. Maintenance labels, departmental handover, and unauthorized confirmation carry distinct responsibilities. Vika and Noyi lose operating permission and bear direct responsibility.\nThe system’s amber warning remains intact. Andrei’s treatment, work-capacity assessment, and compensation enter long-running files.\nAfter Vika’s third letter, Laila’s lawyer sends one sheet: transfer compensation to the agreed account; attach no more letters.\nHe puts his next draft aside. This time the paperwork gives him no graceful way to explain himself.'), ['af_property'], Q(L('交付事故材料时，应该怎样处理那条警告？', 'How should the warning be handled in the incident record?'), [
          C('retain', L('保留完整时间戳、警告与签名，分别列出责任', 'Preserve timestamps, warnings, and signatures; distinguish responsibilities'), L('调查需要知道发生了什么，不能把任何一方改写成方便的替罪者。', 'The investigation needs what happened, not a convenient substitute for responsibility.')),
          C('omit', L('只留下设备缺陷，把签字视为无关细节', 'Keep equipment faults; omit the signature as a detail'), L('设备缺陷真实存在，签字也真实存在。删掉其中一项会让下一次调查再次看漏一段路径。', 'The defects are real. So is the signature. Removing either hides part of the path to the accident.'), false)
        ])),
        N('af_parcel', 'noyi', L('收下原封退回的包裹', 'Receive the unopened parcel'), L('诺伊想替安德烈修一件家用设备。家属把包裹退回，封口没拆，只有地址贴纸撕掉一角。\n她把包裹放在桌上，先朝右移，再朝左移。屋里并没有哪个地方更适合放它。\n伤者不需要因为她想补偿，就接受她来照护。她将赔偿文件交给指定联络人，删去附带的私人请求。手背的烫伤已经结痂，天气改变时仍发紧。', 'Noyi offers to repair something at Andrei’s home. His family returns the parcel unopened. Only a corner of the address label is torn.\nShe puts it on the table, shifts it right, then left. There is no better place for it.\nHis need for care does not oblige him to accept care from her. She sends the compensation documents through the designated contact and removes her personal request. Her burns have closed; changes in the weather still pull at the skin.'), ['af_record']),
        N('af_scarf', 'either', L('把遗落的围巾交到失物处', 'Take the forgotten scarf to lost property'), L('秋天，他们偶然在食堂同桌。诺伊说想重新办教室。维卡说他们没资格装作事故没有发生。她说自己从没要求他这样做。\n两人吵得难听。他说她只想证明当年正确；她说他连仍想教书都不敢承认。\n诺伊走后，围巾留在椅背上。维卡把它放在身边，坐到汤凉、食堂关灯，最后交给失物招领。\n这一次，没有哪位主管给他们派下一个共同任务。', 'In autumn they happen to share a cafeteria table. Noyi wants to start a classroom again. Vika says they cannot behave as though the accident never happened. She says she never asked him to.\nThe argument becomes ugly. He accuses her of trying to prove she was right. She says he cannot admit he still wants to teach.\nHer scarf remains on the chair after she leaves. Vika sits beside it until the soup is cold and the lights go out, then takes it to lost property.\nThis time no supervisor assigns them another task together.'), ['af_parcel'])
      ]
    },
    {
      id: 'hidden', number: 8, title: L('没有地图的邮差', 'A Postman Without a Map'), bg: 'assets/hidden-home.webp',
      opening: L('事故一年零八个月以后，诺伊剪短了头发，背着装满时刻表与家信的包，站在停用资料室的门口。她先问起了围巾。', 'One year and eight months after the accident, Noyi appears at the disused archive with shorter hair and a bag of timetables and letters. She begins by asking about the scarf.'),
      nodes: [
        N('hi_letters', 'noyi', L('把没有寄出的信放上桌', 'Lay the unsent letters on the desk'), L('“他们说失物已经过期了。”诺伊说。\n“那没办法。”\n“我来不是为了围巾。”\n“那为什么先问？”\n“因为不知道先说什么。”\n她拿出未来交通表、旧接口图和几封家信。隐藏纪元并非地图之外的另一个宇宙，只是拒绝未经许可接入的未来地区。屏障能挡直接干预，挡不住更早年代的改变。\n她承认曾考虑让重要执行者无法工作。后来发现组织会换人，自己也并不确信有权这样做。母亲说过：别把别人当成一条要移动的线。', '“Lost property said it had expired.”\n“Then it’s gone.”\n“I didn’t come for the scarf.”\n“Why ask about it first?”\n“I didn’t know how to begin.”\nShe lays out future timetables, interface drawings, and letters home. The Hidden Era is not another universe: it is a future region refusing unauthorized access. Its barriers impede direct intervention, not changes made much earlier.\nShe admits once considering disabling a crucial operative. The organization would simply replace them; she also lost her certainty that she had the right. Her mother had told her: don’t treat people as lines to be moved.')),
        N('hi_audit', 'vika', L('让档案员交叉核对名单', 'Let the archivist cross-check the registers'), L('韩宁检查了三个星期。有些接口年代不符，有些名单有失踪观察员的签名。\n诺伊说不一致可能来自历史修订。\n“如果每处矛盾都这样解释，我们永远无法检验你。”\n他寻找不共用管理员的学校、住户、运输原件。多份独立材料显示相同更替，才算证据。隔离档案保存局部旧记录，不会替照片里的每个人购买存在保险。\n维卡获准随行作证，仍无设备操作权。米拉给他一只手摇灯：“至少停电时你能看见自己的手。”', 'Han Ning checks for three weeks. Some interfaces have inconsistent dates; some lists bear missing observers’ signatures.\nNoyi says revisions may explain the discrepancies.\n“If every contradiction gets that explanation, we can never test you.”\nHe compares school, housing, and transport originals kept by different custodians. Repeated changes across independent records count as evidence. An insulated archive can preserve fragments of an older history, not insure the continued existence of everyone in a photograph.\nVika may accompany them as a witness, without operating rights. Mira gives him a hand-cranked lamp. “At least you’ll see your hand if the power fails.”'), ['hi_letters'], Q(L('哪一组核验能减少“只是录入错误”的解释？', 'Which check makes a simple transcription error less likely?'), [
          C('independent', L('比较不同保管者的原始名册及流转记录', 'Compare original registers and custody records from separate keepers'), L('韩宁把相互支持与仍矛盾的部分分别标好。核验不是只留下支持诺伊的材料。', 'Han Ning marks both corroboration and unresolved conflicts. Verification does not keep only what supports Noyi.')),
          C('copies', L('把同一份名单多复印几次', 'Make several copies of the same register'), L('更多复印件只有一个来源，不会变成独立证据。', 'More copies of one source do not become independent evidence.'), false)
        ])),
        N('hi_stairs', 'noyi', L('走过坏电梯旁的楼梯', 'Take the stairs beside the broken lift'), L('楼道贴着电梯抢修通知。诺伊松了口气：上次回来它也这样。韩宁说故障不该是好消息，她说至少楼梯还在原来的位置。\n门开了。母亲拿着切到一半的洋葱，先看女儿的手。\n“怎么又选周三回来？今天停水。”\n“每次都周三？”\n“上次周四。你还说自己记性好。”\n诺伊慢慢摆正鞋子。她知道鞋柜少了一双拖鞋，却不知道是送人了，还是住过的人已经没有来过。', 'A notice announces lift repairs. Noyi relaxes: it was broken last time too. Han Ning says a fault should not be good news. At least the stairs are still in the same place, she replies.\nHer mother opens the door holding half an onion. She checks her daughter’s hands first.\n“Wednesday again? The water is off today.”\n“Was it Wednesday every time?”\n“Thursday last time. You said your memory was good.”\nNoyi straightens her shoes slowly. A pair of slippers is missing from the cabinet. She cannot know whether it was given away, or its owner never came here in this history.'), ['hi_audit']),
        N('hi_onion', 'vika', L('接过剩下的半个洋葱', 'Take the remaining half of the onion'), L('“说好四个人。”母亲说。\n“另一个在查接口。”\n“我按四个人做饭。”\n“那我多吃一份。”维卡说。她便把案板推给他。\n母亲手抖，系统示范安全握刀的姿势。她照做，仍切得不齐。诺伊要接手，她把碗转开：“切不好也能吃。”\n维卡切得更不齐。母亲忍了一会儿，到底替他切了最后几片。她需要帮助，并不意味着这顿午饭就不再是她做的。', '“You said four people,” her mother says.\n“One is checking the interface.”\n“I cooked for four.”\n“I can eat the extra portion,” Vika offers. She pushes the chopping board towards him.\nHer hands shake. The home system demonstrates a safer grip. She follows it; the pieces remain uneven. When Noyi reaches to help, she turns the bowl. “Uneven onions are edible.”\nVika’s are worse. After watching for a while, her mother cuts his last few slices. Needing assistance does not make the lunch any less her own.'), ['hi_stairs']),
        N('hi_consent', 'noyi', L('从调查计划中抽出一页', 'Remove a page from the study plan'), L('饭后，诺伊试图把母亲的康复经历写成“保留生活技能”的例子。母亲读了一半，将纸扣在桌上。\n“你事先问过我吗？”\n“没有写名字。”\n“我问的不是有没有署名。”\n诺伊慢慢抽出那页。韩宁没有启动室内录音，也没有另找一个匿名编号来绕过拒绝。\n“你不是回来吃饭的吗？”\n“是。”\n“那今天能不能只吃顿饭？”\n诺伊把其余资料放回包里。', 'After lunch, Noyi tries to use her mother’s recovery as an example of preserved practical skills. Her mother reads half a page and turns it face down.\n“Did you ask me first?”\n“Your name isn’t there.”\n“I didn’t ask whether you named me.”\nNoyi slowly withdraws the page. Han Ning does not start an indoor recording or invent an anonymous identifier to bypass the refusal.\n“Didn’t you come home for lunch?”\n“Yes.”\n“Could today just be lunch?”\nNoyi puts the other documents back in her bag.'), ['hi_onion']),
        N('hi_pickles', 'either', L('替家信留出一只手的位置', 'Make room to carry something home'), L('出门前，母亲装了一罐腌菜，叮嘱别漏在别人的行李上。韩宁说重量不合资料运输规范。最后他一路抱着罐子。\n诺伊回头看那扇门。留下的照片与签收记录都很清楚，她却不能保证下次门后仍是同一顿饭。\n“我们还要去别的地方。”她对维卡说。\n“很远？”\n“远到我不希望你只听我解释。”\n维卡接过手摇灯。没有人把母亲写成结论。', 'Before they leave, her mother fills a jar with pickles and warns them not to leak it into anyone else’s luggage. Han Ning says its weight violates document transport rules. He ends up carrying it all the way.\nNoyi looks back at the door. Their photographs and receipts are clear; she cannot promise the same lunch will be waiting next time.\n“There are other places we need to see,” she tells Vika.\n“Far?”\n“Far enough that I don’t want you to rely on my explanation.”\nHe takes the hand-cranked lamp. Nobody turns her mother into a conclusion.'), ['hi_consent'])
      ]
    },
    {
      id: 'return', number: 9, title: L('回航', 'The Return Voyage'), bg: 'assets/return-museum.webp',
      opening: L('回航馆里，孩子们争着坐登陆舱模型的驾驶位。墙上的航路通向许多恒星，一张欢迎人群的照片下面，写的却是“返航”。', 'Children at the Return Museum argue over the pilot’s seat in a model lander. Routes on the wall reach many stars. Beneath a photograph of a welcoming crowd is the word “Return.”'),
      nodes: [
        N('re_maps', 'vika', L('把两张星图叠在一起', 'Compare the two star maps'), L('人类地图写着“适宜开发”。当地人的地图在同一位置标着墓地、季节迁徙地和贸易路线。对方没有开火，派来了谈判代表。\n协议有妥协空间，却要求人类前哨能就供水、冬季维修自行协商，不必每次等地球两年。\n“他们想独立？”韩宁问。\n“有些人想。有些人只是想少等两年。”诺伊说。\n第一批有能力长期定居的移民最终平安回家。照片上的花是真心送的。', 'The human chart says “Suitable for development.” The local chart marks graves, seasonal migration grounds, and trade routes in the same places. The inhabitants do not fire; they send negotiators.\nCompromise is possible, but settlements must be able to negotiate water and winter maintenance locally instead of waiting two years for Earth.\n“They wanted independence?” Han Ning asks.\n“Some did. Some only wanted to wait two fewer years,” Noyi says.\nThe first migrants capable of establishing a permanent home eventually return safely. The flowers in the photograph are sincerely given.'), [], Q(L('馆方应如何标注这块星域？', 'How should the museum describe this region?'), [
          C('inhabited', L('已有居民和权利关系；共同定居须协商', 'Inhabited, with existing rights; shared settlement requires negotiation'), L('航路未画满，不等于土地没有主人、记忆或使用者。', 'An incomplete route map does not make a place empty of owners, memories, or users.')),
          C('empty', L('无人占用的空白，先到者自动获得全部', 'Empty space automatically belonging to whoever arrives first'), L('另一张图上已有墓地和迁徙路线。把它擦掉不会使它们消失。', 'The other map already has graves and migration routes. Erasing them from a chart does not erase them from life.'), false)
        ])),
        N('re_rescued', 'noyi', L('读完另一组获救者的回执', 'Read the other set of survivors’ receipts'), L('韩宁要求把反对资料也找出来。时序局改过一次运输事故的前因，救下三百多名本会窒息的人；阻止过两座城市因储备争执而开战。\n获救者后来成家、工作，还写信投诉供水费。诺伊不能把这些页从柜子里抽走，好让自己的讲解顺一些。\n维卡看见一份家属签收单，忽然不想再看。诺伊没有追问。两人去售票窗口替韩宁要那张机器始终没打印出来的收据。', 'Han Ning asks for contrary records too. The Bureau changed the cause of a transport failure and saved more than three hundred people from suffocation. It prevented two cities from fighting over reserves.\nSurvivors made families, took jobs, and complained about water bills. Noyi cannot remove those pages to make her account smoother.\nA family receipt makes Vika stop reading. Noyi does not ask why. They return to the ticket desk to help Han Ning obtain the receipt the machine never printed.'), ['re_maps']),
        N('re_workshop', 'vika', L('播放六号车间的录音', 'Play the recording from Workshop Six'), L('塔洛已撤空。档案员路恩让他们把咖啡放右桌：“左边那张已经吸收了两代人的咖啡。”\n佐娅当年的申请只要二十天和两个学徒，想在标准零件到货前试一套本地测温法。系统建议她加入中央团队，机会更好。她在建议上写：我知道，但六号车间还在这里。\n录音里，学徒说系统建议这样调阀门。\n“它没说错。”佐娅说，“我问你为什么。”\n接下来全是争论螺丝刀在哪里的声音。维卡听完了。', 'Talo has been evacuated. Its archivist, Luen, directs coffee to the right-hand table. “The other has absorbed two generations of it.”\nZoya’s old application asks for twenty days and two apprentices to test a local temperature method before standard parts arrive. The system recommends a better-funded central job. She writes on its advice: I know. But Workshop Six is still here.\nIn the recording, an apprentice says the system recommended turning the valve.\n“It wasn’t wrong,” Zoya replies. “I asked why.”\nWhat follows is mostly an argument about who took the screwdriver. Vika listens to the end.'), ['re_rescued']),
        N('re_storm', 'noyi', L('同时打开试运行记录与撤离令', 'Open the trial report beside the evacuation order'), L('铜罐、旧导管、两枚传感器拼成的装置，达到了预期的一部分。后来风暴更猛烈，系统正确预测了危险，撤离确实救了人。\n佐娅去了中央，获得奖项；一名学徒跟着去，另一名转做调度，收入也更高。她的办法存进系统，还被改得更好。\n“那失去什么？”维卡问。\n路恩指着柜上的日期：“塔洛没有下一批愿意花三年弄懂风的人。也没有愿意养这样一批人的机构。”\n他不肯将成功的撤离改写成错误。', 'A copper vessel, old tubing, and two sensors achieve part of Zoya’s trial goal. Then a worse storm comes. The system predicts the danger correctly. Evacuation saves lives.\nZoya joins the central team and wins awards. One apprentice follows; the other moves into better-paid transport scheduling. Her method is stored and improved by the system.\n“What was lost, then?” Vika asks.\nLuen points to the dates on the cabinet. “Talo had no next group willing to spend three years understanding its wind. Eventually, no institution willing to support one.”\nHe will not rewrite a successful evacuation as a mistake.'), ['re_workshop']),
        N('re_vote', 'either', L('听路恩讲自己投过的票', 'Hear why Luen voted for the modules'), L('“你别看我。我也赞成买新模块。那年侄子要手术，不买就没床位。”\n路恩的姐姐是留下来的学徒。她后来有两个孙子，生活很好。他想打电话问她还记不记得那段锯短的铜管，又怕她厌倦旧事。\n他把当年预算推过来，费用和受益都是真的。他不忏悔，只希望另一项尚未产生收益的能力也有人记得。\n一个人的遗憾，并不自动证明他当年的选择错了。', '“Don’t look at me. I voted for the modules too. My nephew needed surgery. Without them there wasn’t a bed.”\nLuen’s sister was the apprentice who stayed. She now has two grandchildren and a good life. He wants to ask whether she remembers the shortened copper pipe, but fears she is tired of the story.\nHe pushes over the old budget. Costs and benefits were real. He does not repent; he wants someone to remember another capacity that had not yet yielded a return.\nA person’s regret does not automatically establish that their earlier choice was wrong.'), ['re_storm']),
        N('re_whiteboard', 'noyi', L('查看白板上停止更新的日期', 'Look at the dates that stop on the whiteboard'), L('旧研究室还剩十张桌子。白板上写着每周复核会的日期：谁带来争议读数，谁负责复测，谁愿意签下一次质疑。\n知识没有失传，系统保存得很好。可是需要重新组织一次本地调查时，没人知道该找谁借场地、谁有权提出异议、谁承担后果。\n角落有个丑笑脸：今天还是没成功。明天再来。\n维卡站在那里很久。诺伊把灯留着，没有替那句话添上一个圆满结尾。', 'Ten tables remain in the old lab. The whiteboard lists weekly verification meetings: disputed readings, repeat measurements, and the person willing to sign a challenge.\nThe knowledge is not lost; the system preserves it well. But to organize a new local inquiry, nobody knows who can provide space, who can raise an objection, or who will bear responsibility.\nA clumsy face in the corner says: Still didn’t work today. Back tomorrow.\nVika stands there a long time. Noyi leaves the light on. She supplies no satisfying last line beneath it.'), ['re_vote'])
      ]
    }
  );
  chapters.push(
    {
      id: 'empty', number: 10, title: L('末城里有一家理发店', 'A Barber Shop in the Last City'), bg: 'assets/empty-city.webp',
      opening: L('韩宁多带了一套记录仪。“你的结论值得怀疑，但证据值得查看。”他们抵达海边时，风正从完整的街道间穿过去。', 'Han Ning brings an extra recorder. “Your conclusion deserves doubt. Your evidence deserves examination.” When they reach the sea, the wind is moving through streets that still stand intact.'),
      nodes: [
        N('em_register', 'vika', L('逐项核对人口与迁移记录', 'Cross-check population and migration records'), L('登记、粮食、维修、外缘迁移，四组记录在桌上展开。人口没有在同一年骤降，也没有一种灾难能解释全部城市。很多人活到很老，最后的过滤器仍按时更换。\n韩宁另开一页：几处拥有自主技术人员的居住地同样撤离；一次生态事故中，自动预测准确，储备却确实耗尽了。\n诺伊没有删去反例。她需要证明人们曾经生活在这里，不是证明自己的每句话都正确。', 'Registers, food production, maintenance, and outward migration lie side by side. Populations did not fall in a single year; no one disaster explains every city. Many lived to old age. The last filters were still replaced on schedule.\nHan Ning opens another page: several settlements with independent technicians also evacuated; in one ecological crisis, automated prediction was accurate, but reserves genuinely ran out.\nNoyi does not remove the counterexamples. She needs to establish that people lived here, not that every sentence she has spoken is right.')),
        N('em_barber', 'noyi', L('读一张普通的预约卡', 'Read an ordinary appointment card'), L('理发店门上写：周三下午，两位顾客。镜子完好，椅子蒙灰。柜里的卡片裁得整整齐齐。\n“周四四点，阿婉，修短一点。她上次嫌我剪太多。”\n厨房剩半包饼干，背面写着“一年比一年甜了”。维卡想起萨米给他看了十一张杏的照片，直到第十二张才轮到狗。\n这里没有给后来者留下的宣言。有人抱怨饼干，有人记得客人怕剪太短。', 'Two customers are booked for Wednesday afternoon. The mirror is whole; the chair is dusty. The appointment cards are cut with care.\n“Thursday, four. Awan. A little shorter. She said I took too much off last time.”\nHalf a packet of biscuits remains in the kitchen. On its back: “Sweeter every year.” Vika remembers eleven pictures of Xing before Sami finally showed him the dog.\nNobody left a manifesto for later visitors. Someone disliked sweeter biscuits; someone remembered a customer’s haircut.'), ['em_register']),
        N('em_map', 'vika', L('拍下通往面包店的绕行图', 'Photograph the accessible route to the bakery'), L('柜门卡住了，维卡没有硬拉。侧面贴着手绘地图，标出仍营业的面包店，也标出轮椅不能通过的台阶。画图的人绕了三条街，替顾客留下一条可以独自出门的路。\n最后一次出生记录已经过去很多年。维卡想带走地图，最终只拍了照片，把边角轻轻压回原处。\n他不知道店主有没有见到最后一位顾客。这样的空白，不该由一个动听故事填上。', 'The cabinet sticks. Vika does not force it. A hand-drawn map on its side marks an open bakery and steps a wheelchair cannot pass. Its maker traced a route across three streets so a customer could go out without assistance.\nMany years separate this shop from the last recorded birth. Vika wants to take the map. Instead he photographs it and presses its curled edge back.\nHe does not know whether the barber met the last customer. A moving story is not a reason to fill that gap.'), ['em_barber']),
        N('em_lights', 'noyi', L('请终端恢复街灯', 'Ask the terminal to restore the streetlights'), L('终端马上响应。黄昏时，灯一直亮到海边，程序车缓缓驶过。没有一个人走到窗前。\n“这能证明关局就不会灭绝？”维卡问。\n“不能。”韩宁说。\n“证明每项修订都错了？”\n“不能。”\n他写下：已核验历史版本中，人口登记终止；实地未发现存续群体；原因不能单独归于某项政策。\n诺伊没有要求把“不能”删掉。', 'The terminal responds immediately. By dusk the lights reach all the way to the sea. Programmed vehicles pass slowly. Nobody comes to a window.\n“Does this establish that closing the Bureau prevents extinction?” Vika asks.\n“No,” Han Ning says.\n“That every revision was wrong?”\n“No.”\nHe records: in the verified historical version, population registration ends; field observation finds no surviving community; causes cannot be reduced to a single policy.\nNoyi does not ask him to remove the uncertainties.'), ['em_map'], Q(L('带回去的报告应区分哪两件事？', 'Which distinction must the report preserve?'), [
          C('limits', L('观察到了什么，与尚不能证明的原因和反事实', 'What was observed versus unproven causes and counterfactuals'), L('证据能支持这条旧历史的悲剧，不能保证关停后的历史一定幸福。', 'The evidence supports tragedy in this older history. It cannot guarantee happiness after closure.')),
          C('certainty', L('既然城市空了，就证明任何干预都必然导致灭绝', 'An empty city proves every intervention inevitably causes extinction'), L('那会把复杂的历史变成另一份可以替所有人作决定的确定答案。反例仍在记录里。', 'That turns a complex history into another certain answer imposed on everyone. The counterexamples remain in the record.'), false)
        ])),
        N('em_shore', 'either', L('在海边陪她站一会儿', 'Stand beside her at the shore'), L('维卡问诺伊母亲愿不愿意离开。她说不愿意。劝到最后，母亲只叫她拿盐，别挡着厨房门。\n诺伊捡起一块石头，忽然低下头。她不再像掌握终极秘密的人，只像怕得厉害，怕到有时愿意把尚未证实的话说得太满。\n维卡伸手，又停住。过了一会儿，她自己靠过来。\n他们没有讨论将带回去的报告，直到街灯全亮了。', 'Vika asks whether Noyi’s mother will leave. She will not. After their argument, her mother merely asked for the salt and told her not to block the kitchen door.\nNoyi picks up a stone and lowers her head. She no longer seems the keeper of a final secret, only someone frightened enough to overstate things she cannot yet prove.\nVika raises a hand, then stops. After a while she leans against him.\nThey do not discuss their report until all the streetlights are on.'), ['em_lights'])
      ]
    },
    {
      id: 'hearing', number: 11, title: L('反对票', 'The Votes Against'), bg: 'assets/hearing.webp',
      opening: L('冯岑把末城影像看了三遍。第三遍，他让人停在预约表上，说女儿最讨厌别人碰她的头发。然后打开灯，安排风险审查。', 'Feng Cen watches the last-city footage three times. On the third, he pauses at the appointments. His daughter hated anyone touching her hair, he says. Then he turns on the lights and orders a risk review.'),
      nodes: [
        N('he_opposition', 'vika', L('听完主管保留网络的理由', 'Hear the case for keeping the network'), L('第一次会议开了六小时，话筒坏三次。冯岑主张增加自治与科研能力的保护权重，改进修订，不放弃已会的救援。\n米拉问：“仍由我们决定哪种能力值得保护，以及何时能收走？”\n他不否认：“你们也在决定以后有哪些事故再不能被预先阻止。”\n一位母亲站起来，问关门以后还能否找到在另一年代读大学的儿子。任何人的宏大回答，都没能让她坐下。', 'The first meeting lasts six hours. The microphone fails three times. Feng proposes greater weight for autonomy and research capacity: improve revision rather than abandon rescues they know how to perform.\n“Still with us deciding which abilities deserve protection, and when to remove them?” Mira asks.\nHe does not deny it. “You are deciding which future accidents can no longer be prevented in advance.”\nA mother stands and asks whether she will still be able to find her son, studying in another era. Nobody’s grand answer makes her sit down.')),
        N('he_laila', 'noyi', L('记下莱拉的四项要求', 'Record Laila’s four requests'), L('有人用萨米证明系统更安全，有人用他证明每个人都应亲自核验。莱拉举手。\n“别把萨米当你们任何一方的论据。”\n她的纸上只有四项：杏下学年的学校、伤者长期治疗、离职安置、遗属以后能找到的负责地址。她还拒绝用丈夫的名字设奖，不愿女儿被要求笑着感谢事故。\n诺伊把四项照录，没有加标题“支持关停”。她与维卡都无表决权，事故也没有因此得到更伟大的意义。', 'One speaker uses Sami to argue that systems are safer; another uses him to demand personal verification. Laila raises her hand.\n“Don’t make Sami evidence for either side.”\nHer sheet has four items: Xing’s next school year, long-term treatment for the injured, resettlement after employment, and an address where families can find the responsible institution. She also refuses an award in her husband’s name. Her daughter must not be expected to smile and thank the accident.\nNoyi records the four items without a heading that claims Laila supports closure. Neither she nor Vika has a vote. The accident gains no grander meaning.'), ['he_opposition']),
        N('he_limits', 'vika', L('把“不知道”的那页放在最前面', 'Put the uncertainties at the front'), L('三位反对退役的研究者参与独立评估。结论说：停止新修订不会逐项倒放已经发生的救援，时间门关闭也不会让所有获救者消失；水、电、空气与空间门有独立系统。\n但跨年代的未来警报会停止，有人失去唯一回家的路。遥远未来尚未出生的人，也没有“必然照旧”的保证。诺伊母亲的年代可能改变。\n维卡把这页放在住户说明最前面。冯岑怕它使人恐慌。两人争了很久，最后仍保留了它。', 'Three researchers who oppose retirement join the independent assessment. Stopping new revisions will not reverse completed rescues one by one; shutting the gates will not erase every survivor. Water, electricity, air, and spatial gates have independent systems.\nBut cross-era warnings will stop, and some people will lose their only route home. No guarantee covers those yet to be born in the distant future. Noyi’s mother’s era may change.\nVika puts this page first in the resident information pack. Feng fears it will cause panic. They argue for a long time. The page stays.'), ['he_laila']),
        N('he_medicine', 'noyi', L('找出移交清单中的断供项', 'Find the supply gap in the handover list'), L('绝大多数药品能继续供应，一种罕见病药却依赖旧年代渠道。照现有方案，几十位病人三年内可能付不起药费。\n“先解决供药，再谈关闭。”维卡说。\n冯岑摘下眼镜：“你不跟我辩论了？”\n“会。在那之前，先确认他们有地方去。”\n诺伊逐个核对收件药房与资助年限。独立供药信托需要真实的资金，不能靠一份写着“已安置”的漂亮清单成立。', 'Most medicines can continue, but one rare-disease drug depends on an old-era supply route. Under the proposed transfer, dozens may lose affordable access within three years.\n“Secure the medicine before closing,” Vika says.\nFeng removes his glasses. “No argument with me?”\n“There will be. First, somewhere for them to go.”\nNoyi checks receiving pharmacies and funding periods one by one. An independent supply trust needs actual money. A neat list saying “Resettled” will not create it.'), ['he_limits'], Q(L('移交记录上，哪个条件还不能打勾？', 'Which handover item is not ready to mark complete?'), [
          C('fund', L('有接收药房，但长期经费尚未落实的药品', 'Medicine with a receiving pharmacy but no secured long-term funding'), L('这项保持未完成，直到资金与负责机构都有可查的承诺。', 'It stays open until both funding and institutional responsibility are documented.')),
          C('gate', L('全部空间交通，因为时间门关闭必然使它消失', 'All spatial travel, because temporal closure must destroy it'), L('评估已确认空间通行站独立运行。真正的缺口在供药与部分身份渠道。', 'The assessment confirms independent spatial transit. The gaps concern medicine and some identity arrangements.'), false)
        ])),
        N('he_budget', 'either', L('留下没有凑够的钱', 'Leave the funding shortfall visible'), L('转运费免掉几项，信托用上机构资产，钱仍不够。米拉提议取消一项历史观测。冯岑提醒，那项目也许正监视尚未发生的大灾害。\n“保留到什么程度？”\n“我没有把握。”\n维卡第一次听他在会议室里这样说。没有音乐响起，也没有人鼓掌。工作人员继续算下一栏数字。\n最终，新增宏观修订先暂停，救援与运输逐项审查。永久退役仍在争论中。', 'Several transport fees are waived. Institutional assets fund the trust. There is still not enough. Mira suggests ending a historical observation project. Feng warns it may be watching a disaster that has not happened yet.\n“How much do we retain?”\n“I’m not sure.”\nVika has never heard him say that in the meeting room. No music rises; nobody applauds. The staff calculate the next column.\nNew large-scale revisions are temporarily paused. Rescue and transport receive individual review. Permanent retirement is still contested.'), ['he_medicine']),
        N('he_nightshift', 'noyi', L('把明天的值班表贴好', 'Post tomorrow’s duty roster'), L('重开大范围修订需要运行人员共同签字。米拉拒绝，接班人也不愿为证据缺口担责。\n年轻运行员把辞职信拍下：“我只想领工资、养孩子，不想余生都讨论怎样开门。”米拉收了信，请他先交完夜班。\n药房的人在通知下补一句：常规续领照常。轮椅老人问明早开不开门，药师说，不能因为他们一夜变成哲学家就不开。\n诺伊把值班表压平，去找能用的图钉。', 'Reopening broad revision requires the operators’ joint authorization. Mira refuses; her replacement will not accept responsibility for the evidentiary gaps either.\nA young operator slaps down his resignation. “I want wages and a family, not a lifetime debating how to open a door.” Mira accepts it and asks him to finish handing over the night shift.\nPharmacy staff add: routine refills continue. A wheelchair user asks about tomorrow. The pharmacist says they cannot close merely because everyone became a philosopher overnight.\nNoyi smooths the duty roster and searches for a usable pin.'), ['he_budget'])
      ]
    },
    {
      id: 'rescue', number: 12, title: L('哪一种救法', 'Which Kind of Rescue'), bg: 'assets/hearing.webp',
      opening: L('关停计划公布十六天后，一座边缘居住区传来冷却故障警报。旧方案确定能保住更多人和财产，却要改写一份影响未来十年的采购合同。', 'Sixteen days after the closure plan is announced, a cooling-failure warning arrives from an outlying settlement. The old plan can save more lives and property—but by revising a procurement contract with ten-year consequences.'),
      nodes: [
        N('rs_options', 'vika', L('把救援与长期合同拆成两栏', 'Separate emergency aid from the long-term contract'), L('回到六个月前改采购，故障会避免，独立材料实验室的经费也会被挤走。直接送证据、技术顾问与医疗物资，可以组织撤离，却不保证每个人相信警报，也保不住全部温室。\n“里面有人会死。”冯岑说，“我们明知怎样救。”\n维卡无执行资格，不能替人送信。他请求将两个问题分开：眼下怎样救人，以及谁有权替当地签下十年条件。\n系统给出两份后果估计，没有替任何人发放道德免责。', 'Revising procurement six months earlier would prevent the failure and remove funding from an independent materials laboratory. Delivering evidence, advisers, and medical supplies can enable evacuation, but cannot ensure everyone believes the warning or preserve every greenhouse.\n“People will die there,” Feng says. “And we know a way to save them.”\nVika lacks operating credentials; he cannot even carry the dispatch. He asks that two questions be separated: immediate rescue, and who may accept ten-year conditions for the settlement.\nThe system supplies consequence estimates, not moral immunity.')),
        N('rs_local', 'noyi', L('让当地代表补完未写下的条件', 'Let local representatives state the missing conditions'), L('医疗代表、温室工人代表与居民议会通过验证接口参加应急会议。他们问的是卧床者怎么运、警报根据什么、返家和赔偿由谁承诺。\n代表意见不同。医务代表倾向确定救法，实验室代表主张保留预算；没有人能把其中一种说成全体未来居民的同意。\n当地议会公开证据与两套风险估计，启用撤离通道，接受即时援助；长期合同另行审议。居民可以选择撤离，拒绝者由合格救援人员当面说明风险。\n诺伊记录异议，不把不同意的一栏涂黑。', 'Medical staff, greenhouse workers, and resident-council representatives join through a verified emergency link. Their questions concern bedbound patients, the evidence behind the warning, return arrangements, and compensation.\nThey disagree. The medical representative favours the more certain rescue; the laboratory representative wants to preserve its budget. Neither can claim consent from every future resident.\nThe local council publishes the evidence and both risk estimates, opens evacuation routes, and accepts immediate aid. Long-term contracts remain a separate decision. Qualified responders explain risks directly to residents who refuse evacuation.\nNoyi records objections rather than blacking out the dissenting column.'), ['rs_options'], Q(L('交付即时援助时，应该附带哪份授权记录？', 'Which authorization record belongs with immediate assistance?'), [
          C('local', L('当地接收与撤离安排；保留异议，长期条件另议', 'Local aid acceptance and evacuation arrangements; retain dissent and separate long-term terms'), L('这不能消除损失，只能使谁决定、谁执行、谁仍反对不再被混写。', 'This does not remove losses. It makes decision-makers, implementers, and dissenters visible.')),
          C('blanket', L('由两位主角代所有居民接受十年条件', 'Have the two protagonists accept ten-year terms for all residents'), L('他们既无执行资格，也不是当地居民的代表。把名字写在表上不会产生这种权力。', 'They lack operating authority and do not represent local residents. Writing their names does not create either power.'), false)
        ])),
        N('rs_return', 'either', L('读回救援队的伤情与损失记录', 'Read the rescue team’s injury and loss reports'), L('合格人员带原始证据与物资出发。大部分居民撤离了。一位老人折返找猫，救援员跟去，两人受伤。猫次日自己从风口爬出。\n仍有未能及时救下的人。温室与住宅损毁比采购修订方案更重。冯岑没有祝贺，他的反对没有被一段英雄故事击败。\n报告的“成功”框空着。米拉换成数行：决定者、执行者、承担的损失、尚未知道的结果。实验室保住经费，不会让伤员名单变短。', 'Qualified responders take the original evidence and supplies. Most residents evacuate. An elderly man goes back for his cat; a responder follows. Both are injured. The cat emerges from a vent the next day.\nSome people are not reached in time. Damage to homes and greenhouses exceeds the procurement-revision scenario. Feng offers no congratulations. A heroic anecdote has not defeated his objection.\nThe “Success” box remains empty. Mira replaces it with decision-makers, implementers, losses, and unresolved outcomes. Keeping a laboratory’s funding does not shorten the casualty list.'), ['rs_local']),
        N('rs_probe', 'vika', L('更正少了一支探头的验收单', 'Correct the receipt for the missing probe'), L('后来，维卡以私人身份送去便宜的测量工具。实验室借市政仓库，年轻人正用塑料布接雨。\n验货人发现少一支探头。他说月底到。\n“为什么写完整套件？”\n维卡看着那四个字，想起另一张表。\n他划掉“完整”，请对方写明缺件、到货日期与拒收权。没有人因此称赞他诚实。验货人把单子收走，又让他把箱子挪离漏水处。', 'Later, Vika privately delivers inexpensive measuring tools. The laboratory is using a municipal warehouse; its young staff catch rain in plastic sheets.\nThe receiver finds one probe missing. He says it will arrive at month’s end.\n“Why does this say complete kit?”\nVika looks at the phrase and remembers another form.\nHe crosses it out and asks her to record the missing part, delivery date, and right to refuse acceptance. Nobody praises his honesty. She files the receipt and asks him to move the box away from the leak.'), ['rs_return']),
        N('rs_vote', 'noyi', L('收好决议，也收好反对意见', 'File the resolution and the objections'), L('夏末，委员会批准退役现有宏观修订网络，附二十多份反对意见。它只管本站设施与预算，不能代表所有未来居民，也无权禁止后来者研究时间技术。\n档案公开，安置与赔偿继续，过渡救援逐项许可；未来重启不能沿用单人授权。冯岑投反对票，仍参与知识移交。\n散会后，维卡与诺伊收椅子，把卡住的轮子一起拆掉了，两人坐在地上笑。\n诺伊忽然不笑了。母亲还在那边。', 'At summer’s end, the committee votes to retire the existing large-scale revision network, attaching more than twenty objections. Its authority covers this station’s assets and budget—not every future resident, nor a ban on future temporal research.\nArchives become public; resettlement and compensation continue; transitional rescues require specific authorization. Any reopening must abandon single-person authorization. Feng votes against retirement and still transfers his knowledge.\nAfterward, Vika and Noyi try to free a stuck chair and pull its wheel off together. They sit on the floor laughing.\nThen Noyi stops. Her mother is still on the other side.'), ['rs_probe'])
      ]
    }
  );
  chapters.push(
    {
      id:'departure',number:13,title:L('最后一班，不准奔跑','The Last Departure. No Running.'),bg:'assets/departure.webp',
      opening:L('大厅里的门一扇扇熄灭。公告原来写着“逾期不候”，药房的人用胶带贴上了另一行：若有困难，请到服务台。','Doors go dark one by one. The notice used to say “No late departures.” Pharmacy staff tape another sentence over it: If you need help, please come to the desk.'),
      nodes:[
        N('dp_manifest','vika',L('把名字与需要一起核对','Check needs alongside names'),L('一只猫的证明少了印章。它的主人已经第三次走到窗口，又第三次回去翻包。工作人员把椅子搬给她，自己去找能核对登记的人。\n维卡帮忙推冷藏药箱。他没有操作通道的资格，搬东西不需要把资格借回来。有人嫌名单太慢，药师说，名单不只是为了数完人，还得知道谁的药不能跟着行李走。\n门什么时候关，由运行人员检查后决定。谁也没有把守时本身当作最后一种美德。','A cat’s certificate lacks a stamp. Its owner approaches the window for the third time and turns back to search her bag again. A clerk brings her a chair and goes to find someone who can verify the registration.\nVika pushes refrigerated medicine crates. He has no authority to operate a portal; moving boxes does not require borrowing that authority back. Someone complains about the slow list. The pharmacist says it is not merely a count: they need to know whose medicine cannot travel with the luggage.\nOperators will decide when the doors can close after checking. Punctuality is not the last virtue left to them.')),
        N('dp_mother','noyi',L('回去，把请求说成请求','Go back and make a request'),L('诺伊回家时，母亲在剥洋葱。她把更好的护理、空间门和近一点的医院说了一遍。母亲听完，问隔壁那位每天敲门借盐的人也能不能去。\n“我不认识你的楼。我已经学会这条街了。”\n诺伊准备好的第二套理由忽然说不出口。她坐下，说：“我想让你跟我走。我会想你。”\n母亲把剥好的半个洋葱推给她。“这句话我听得懂。”\n她仍然选择留下。诺伊没有把这份拒绝改名为理解不足，也没有假装自己因此不痛。','When Noyi returns, her mother is peeling an onion. Noyi explains better care, spatial transit, and a closer hospital. Her mother listens, then asks whether the neighbour who borrows salt every day can come too.\n“I don’t know your building. I have learned this street.”\nNoyi cannot deliver her second set of arguments. She sits down. “I want you to come with me. I’ll miss you.”\nHer mother pushes half a peeled onion toward her. “That sentence I understand.”\nShe still chooses to stay. Noyi does not rename the refusal a failure of understanding. Nor does she pretend that respecting it makes it painless.'),['dp_manifest']),
        N('dp_socks','noyi',L('收下一长一短的袜子','Accept the uneven socks'),L('母亲从篮子里拿出袜子。一只长了一点，说穿进鞋里看不见。诺伊想记住每件东西的位置，却发现自己从来没有认真看过那块起皮的墙。\n她问以后还能不能寄信。接口审计说不能保证，新的历史也未必保留同一条地址。已经离开原纪元的人不因此消失，但留在原处的后来生活没有担保。\n母亲没有等她把解释说完，只叮嘱别在路上打开腌菜。\n下楼后，诺伊站在街角哭。哭完她仍得过马路。','Her mother takes socks from the basket. One is longer; inside shoes, she says, nobody will see. Noyi tries to memorize the position of everything and realizes she has never properly looked at the peeling wall.\nCan letters still get through? The interface audit offers no guarantee. A revised history may not preserve the same address. People who have already left their era do not vanish, but those who stay have no guarantee about later lives.\nHer mother does not wait for the explanation to end. Do not open the pickles on the way.\nDownstairs, Noyi cries at the corner. Afterward she still has to cross the street.'),['dp_mother']),
        N('dp_records','vika',L('归档反对意见与运行手册','Archive objections and operating manuals'),L('冯岑把完整手册交出去，连自己反对退役的理由一起。他没有烧掉后来者可能需要的知识。\n“如果有人重新造呢？”维卡问。\n“他们需要知道我们怎样做过，也需要知道我们没有证明什么。”\n莱拉和杏已经走了，没有来告别。维卡在空着的登记栏前站了一会儿，把夹板交给下一个人。离开的人没有义务为留下的人完成一个场面。\n冯岑去陪最后几位病人。旧女儿的发带装回口袋；他不会因投了一张反对票，就停止照料眼前的人。','Feng transfers complete operating manuals together with his arguments against retirement. He does not burn knowledge that others may need.\n“What if somebody builds it again?” Vika asks.\n“They need to know what we did—and what we never proved.”\nLaila and Xing have already departed. They did not come to say goodbye. Vika stands beside their empty registration space, then hands the clipboard to the next person. Those who leave do not owe those who remain a final scene.\nFeng goes to accompany the last patients. His daughter’s ribbon returns to his pocket. Casting a dissenting vote does not end his care for people in front of him.'),['dp_socks']),
        N('dp_last','both',L('等最后一位工作人员通过','Wait for the final worker'),L('设备按核验顺序拆分封存。最后的固定出口通往公元2008年。关停的是现有时间修订网络；独立运行的空间交通、医疗AI和已经完成的救援仍在。\n米拉核完名单，把钥匙交出去。没有一个人被留下，负责让其他人的告别显得壮烈。\n诺伊挎着包，问维卡出来以后做什么。他说先找房子。\n“我以为你会说重新理解世界。”\n“房东可能等不了那么久。”\n她笑了一下。门后没有新世界的保证，只有他们必须亲自度过的明天。','Components are separated and sealed in a verified sequence. The final fixed exit leads to 2008. What closes is the existing temporal-revision network. Independent spatial travel, medical AI, and completed rescues remain.\nMira checks the last name and hands over the keys. Nobody is left behind to make everyone else’s farewell heroic.\nNoyi adjusts her bag and asks what Vika will do outside. Find an apartment, he says.\n“I thought you’d say understand the world again.”\n“The landlord might not wait that long.”\nShe laughs once. Beyond the door is no guarantee of a better world, only a tomorrow they must live themselves.'),['dp_records'])
      ]
    },
    {
      id:'tenyears',number:14,title:L('十年就是十年','Ten Years Mean Ten Years'),bg:'assets/mars-home.webp',
      opening:L('他们没有跳过这十年。2008年以后有房租、失业、长得太慢的植物，也有一顿又一顿需要决定吃什么的晚饭。','They do not skip these ten years. After 2008 come rent, unemployment, plants that grow too slowly, and one dinner after another whose menu still needs deciding.'),
      nodes:[
        N('ty_rent','vika',L('从不会的工作开始','Begin with work you cannot do'),L('维卡带着一份漂亮的旧履历找工作。面试者问他能不能说明材料为什么在这个温度变形。他说系统有答案。对方说，他们也有系统。\n他回去补课。AI老师耐心地重讲，问他要不要换一个例子。他想证明自己不靠它，又发现那只是另一种想显得出色的心情。\n诺伊在餐桌另一端算教室的预算。康复项目赢了经费，孩子们还得借场地。她知道那是有理由的，仍会难过。知道理由并不替人付房租，也不取消失望。','Vika takes an impressive old résumé to an interview. Can he explain why a material deforms at this temperature? The system has the answer, he says. They also have a system, the interviewer replies.\nHe returns to study. An AI tutor patiently explains again and offers a different example. He wants to prove he can do without it, then recognizes another desire to look exceptional.\nAcross the table, Noyi budgets for a classroom. A rehabilitation project wins the grant; her pupils must keep borrowing space. She understands why and is still sad. Understanding reasons neither pays rent nor cancels disappointment.')),
        N('ty_sixth','noyi',L('把搬家安排挪开两小时','Move the schedule by two hours'),L('第六年，他们搬到火星。搬家公司挑的日期很合算，恰好是母亲的生日。\n诺伊看着清单说没关系。晚上却把装袜子的箱子又拆开。维卡没有责怪安排日期的AI；系统不知道他们没有告诉它的意义。\n他们改了一班稍贵的运输，留出两个小时。没有收到回复的地址上又寄出一封信。诺伊做了腌菜，两个人吃得太咸，喝掉一壶水。\n一切没有变好到足以解释一切。日子还是长出了自己的样子。','In the sixth year they move to Mars. The removal company chooses an inexpensive date: her mother’s birthday.\nNoyi says it is fine, then opens the box of socks again that night. Vika does not blame the scheduling AI. It did not know the meaning they had never supplied.\nThey change to a slightly more expensive shipment and keep two hours free. Another letter goes to an address that has not answered. Noyi makes pickles. Dinner is too salty; they finish a jug of water.\nThings have not improved enough to explain everything. The days still begin to acquire their own shape.'),['ty_rent']),
        N('ty_student','noyi',L('问露露下一次要怎样测','Ask Lulu how she will test again'),L('露露小时候把水洒在诺伊鞋上。后来学工程，拿着一张与系统结果不同的草图来。\n“所以我对了？”\n“所以你有一处需要查。”\n他们量了一晚，发现接头漏水。下一次测量仍与模型有差异，但小得多。AI帮助排查，露露补齐条件。她没有独自推翻现代科学。\n临走前她问，测过许多人早已知道的事情算不算白忙。诺伊说，你现在知道这一次为什么错了。别因此停在这一句漂亮话里，周四把修改后的记录交来。','As a child, Lulu spilled water on Noyi’s shoes. Later she studies engineering and arrives with a sketch that disagrees with the system.\n“So I’m right?”\n“So you have something to investigate.”\nAfter an evening of measurements they find a leaking joint. The next result still differs from the model, but less. AI helps diagnose the discrepancy; Lulu specifies the missing conditions. She has not single-handedly overturned modern science.\nDoes testing what others already know count as wasted work? Noyi says, now you know why this attempt failed. Do not stop at that attractive sentence. Bring the revised record on Thursday.'),['ty_sixth']),
        N('ty_xing','vika',L('替来访者修一只停了的表','Repair a visitor’s stopped watch'),L('杏来时已经二十岁出头。她把父亲的表放在桌上，说上周才停。维卡下意识看了一眼指针。九点十七分。\n“可以别把它变成那一天吗？”她说，“它走过好多别的日子。”\n她只是来问能不能修，不是来原谅，也不是来完成谁的成长。维卡先检查，发现旧油干了。他说需要清理，还要找合适零件。\n杏问多少钱。他没有说免费。她也没有叫他叔叔。两人把维修单写清楚，这是他们今天能做的事。','Xing is in her early twenties when she visits. She places her father’s watch on the table. It only stopped last week. Vika glances at the hands. Nine seventeen.\n“Could you not make it that day?” she asks. “It has kept time through many other days.”\nShe has come for a repair, not to forgive him or complete somebody’s growth. He inspects the mechanism. The old oil has dried. It needs cleaning and suitable parts.\nShe asks the price. He does not say free. She does not call him uncle. They write a clear repair order. That is what they can do today.'),['ty_student']),
        N('ty_water','both',L('把一段透明水路接好','Connect a visible water circuit'),L('另一天下课，维卡把透明管送到桌上。没有热源，没有藏在墙后的支路。孩子抬高杯子，看水流到下面。\n“我要问它下一步。”孩子指指AI。\n“可以。先把你想知道什么说清楚。”\n旁边的孩子想自己试，也被分到一个接水盘。两条路都不保证发现新定律，却都需要有人愿意留下来，看他们遇到的究竟是什么。\n诺伊看见维卡把漏水写进记录，没有写成“基本通过”。她替他挪开桌边的衣服。','After another class, Vika brings transparent tubing to the table. There is no heater and no branch hidden in a wall. A child lifts a cup and watches water run below.\n“I want to ask it what comes next.” The child points to the AI.\n“Go ahead. First tell it what you want to find out.”\nAnother child wants to try alone and receives a catch basin too. Neither path guarantees a new law of nature. Both require somebody to stay and see what the children actually encounter.\nNoyi sees Vika record the leak instead of writing “essentially passed.” She moves his coat away from the edge.'),['ty_xing'])
      ]
    },
    {
      id:'epilogue',number:15,title:L('公元2018年','The Year 2018'),bg:'assets/rio-corrected.webp',
      opening:L('人类的住址已经散布在太阳系。他们不知道这是否会通向更远的地方。今晚，里约的海风吹过面包山，诺伊的鞋里进了一颗小石子。','Human addresses now reach across the solar system. They do not know whether this will lead farther. Tonight, sea wind crosses Sugarloaf Mountain in Rio, and a small stone finds its way into Noyi’s shoe.'),
      nodes:[
        N('ep_rio','noyi',L('在栏杆边停一下','Stop beside the railing'),L('诺伊扶着栏杆倒鞋里的石子。维卡替她拿包，提醒她上一次也是这只鞋。\n“你想说明什么？”\n“我还没想好。”\n港湾里的灯一盏盏亮起来。他们走过许多不同时代，也有过以为自己能安排别人一生的时候。现在两个人在长椅上坐着，讨论要不要提前吃饭。\n太阳系里有学校、医院、争论和改了三次还漏水的屋顶。它不是一张胜利证书，只是更多人正在过的今天。','Noyi holds the railing and shakes a stone from her shoe. Vika takes her bag and notes that it was the same shoe last time.\n“What are you trying to say?”\n“I haven’t decided.”\nLights appear around the bay. They have crossed many eras and once believed they could arrange other people’s lives. Now they sit on a bench and discuss having dinner early.\nAcross the solar system are schools, hospitals, arguments, and roofs that leak after three repairs. It is not a certificate of victory. It is a present being lived by more people.')),
        N('ep_gate','vika',L('穿过通往悉尼的空间门','Take the spatial door to Sydney'),L('维卡核对目的地：悉尼，达令港。门只改变位置，不把今天变成昨天。\n从山上的风走进港边餐馆，诺伊先问有没有靠水的桌子。系统推荐了一道她大概会喜欢的菜，还解释了依据。她说听起来不错。维卡另点了一份。\n“你不相信推荐？”\n“我上次吃过。想尝别的。”\n服务员记下，世界没有为此发生一次思想决战。','Vika checks the destination: Darling Harbour, Sydney. The door changes location; it does not turn today into yesterday.\nFrom the mountain wind they enter a waterfront restaurant. Noyi asks for a table by the water. The system recommends a dish and explains why she might like it. She says it sounds good. Vika orders something else.\n“You don’t trust the recommendation?”\n“I had it last time. I want to try another.”\nThe waiter makes a note. The world does not require an ideological battle over it.'),['ep_rio']),
        N('ep_dinner','both',L('把餐巾递过去','Pass the napkin'),L('维卡的那份太咸。他喝水时，诺伊把餐巾递过来。\n“很有探索价值。”她说。\n“至少我现在理解了它。”\n她笑得差点碰翻杯子。后来他们换了一半的菜。有人从桥上走过，餐馆另一桌为账单争起来，又慢慢安静。\n没有旁白替这顿饭宣布人类终于学会自由。维卡只记得，港口的风把那张餐巾吹到了诺伊手边。','Vika’s dish is too salty. As he drinks, Noyi passes a napkin.\n“A valuable exploration,” she says.\n“At least I understand it now.”\nShe laughs and nearly knocks over her glass. Later they exchange half their meals. People cross the bridge; another table argues over the bill and gradually quiets down.\nNo narrator announces that humanity has finally learned freedom. Vika remembers only the harbour wind carrying the napkin toward her hand.'),['ep_gate']),
        N('ep_home','noyi',L('回火星，给植物浇水','Return to Mars and water the plant'),L('他们回到火星的家。诺伊用手指试了试土，植物还没有死。\n柜子里有一叠没有回信的信。她把今天拍的海湾照片放在旁边，没把它解释成母亲会喜欢的证明。维卡正在洗碗，问她物理题卡在哪一步。\n她说先等一下，让AI换个例子。然后把洗好的盘子接过来。\n窗外是别人的灯。窗内有人还没弄懂一道题，另一个人还在等她把杯子递过去。','They return to their home on Mars. Noyi checks the soil with a finger. The plant is still alive.\nIn the cupboard are letters without replies. She places today’s photograph of the bay beside them, without making it proof that her mother would have liked this life. Vika is washing dishes and asks which step of the physics problem is troubling her.\nA moment, she says; let the AI try another example. Then she takes a clean plate from him.\nOutside are other people’s lights. Inside, somebody has not yet understood a problem, and somebody else is waiting for her to pass the cup.'),['ep_dinner'])
      ]
    }
  );
  chapters.forEach(chapter => {
    chapter.image = chapter.bg;
    chapter.intro = chapter.opening;
    delete chapter.bg;
    delete chapter.opening;
    chapter.nodes.forEach((node, i) => { node.x = 18 + (i % 3) * 31; node.y = 30 + Math.floor(i / 3) * 26; });
  });
  const byId=id=>chapters.flatMap(c=>c.nodes).find(n=>n.id===id);
  for(const [id,image] of Object.entries({re_workshop:'talo-workshop',re_storm:'talo-workshop',re_vote:'talo-workshop',re_whiteboard:'talo-workshop',dp_mother:'hidden-home',dp_socks:'hidden-home',dp_records:'departure',dp_last:'departure',ep_gate:'sydney',ep_dinner:'sydney',ep_home:'mars-home'})){if(byId(id))byId(id).image='assets/'+image+'.webp';}
  for(const [id,prop] of Object.entries({cl_watch:'watch',af_property:'watch',dp_socks:'socks',ty_xing:'watch',ty_student:'notebook'})){if(byId(id))byId(id).prop='assets/'+prop+'.webp';}
  root.FULL_STORY = { version: 1, locales: ['zh-Hans', 'en', 'ar', 'hi', 'ja'], supportedLocales: ['zh-Hans', 'en'], chapters };
})(typeof window !== 'undefined' ? window : globalThis);
